parameters.jsCode:
const originalQuestion = String(
  $json.question ?? $json.Question ?? ''
).trim();

const history = Array.isArray($json.history)
  ? $json.history
      .filter(
        (message) =>
          message &&
          typeof message.content === 'string' &&
          ['user', 'assistant'].includes(message.role)
      )
      .slice(-6)
  : [];

/*
 * The frontend may include the current question as the final history item.
 * Remove that duplicate before looking for earlier conversation context.
 */
const previousHistory = [...history];

const lastHistoryMessage =
  previousHistory[previousHistory.length - 1];

if (
  lastHistoryMessage?.role === 'user' &&
  lastHistoryMessage.content.trim() === originalQuestion
) {
  previousHistory.pop();
}

/*
 * Keep all earlier user messages in reverse order.
 * This allows the classifier to skip vague messages such as
 * "How to contact?" and continue backward until it finds
 * a message with a recognizable topic.
 */
const previousUserMessages = [...previousHistory]
  .reverse()
  .filter((message) => message.role === 'user');

const previousAssistantMessage = [...previousHistory]
  .reverse()
  .find((message) => message.role === 'assistant');

const previousAssistantAnswer =
  previousAssistantMessage?.content?.trim() ?? '';

function classifyTopic(input) {
  const question = String(input ?? '').toLowerCase();

  let topic = null;

  // 1. Payment arrangement must come before repayment,
  // because phrases such as "cannot repay" contain the word "repay".
  if (
    question.includes('one payment') ||
    question.includes('single payment') ||
    question.includes('cannot repay') ||
    question.includes("can't repay") ||
    question.includes('can not repay') ||
    question.includes('unable to repay') ||
    question.includes('cannot pay') ||
    question.includes("can't pay") ||
    question.includes('payment arrangement') ||
    question.includes('personal payment arrangement') ||
    question.includes('pay in instalments') ||
    question.includes('pay in installments') ||
    question.includes('pay monthly') ||
    question.includes('monthly payment') ||
    question.includes('spread the payment') ||
    question.includes('24 months') ||
    question.includes('betalingsregeling')
  ) {
    topic = 'payment_arrangement';

  // 2. Repayment
  } else if (
    question.includes('why do i have to repay') ||
    question.includes('why must i repay') ||
    question.includes('why should i repay') ||
    question.includes('repay part') ||
    question.includes('repay my allowance') ||
    question.includes('pay back') ||
    question.includes('paid too much') ||
    question.includes('received too much') ||
    question.includes('owe money') ||
    question.includes('terugbetalen')
  ) {
    topic = 'repayment';

  // 3. Objection
  } else if (
    question.includes('objection') ||
    /\bobject\b/.test(question) ||
    question.includes('disagree') ||
    question.includes('challenge the decision') ||
    question.includes('appeal the decision') ||
    question.includes('bezwaar')
  ) {
    topic = 'objection';

  // 4. Review request
  } else if (
    question.includes('review request') ||
    question.includes('request a review') ||
    question.includes('ask for a review') ||
    question.includes('decision to be reviewed') ||
    question.includes('decision reviewed') ||
    question.includes('review the decision') ||
    question.includes('reconsider') ||
    question.includes('reconsideration') ||
    question.includes('herzien') ||
    question.includes('herziening')
  ) {
    topic = 'review_request';

  // 5. Definitive calculation
  } else if (
    question.includes('definitive calculation') ||
    question.includes('final calculation') ||
    question.includes('definitive assessment') ||
    question.includes('final assessment') ||
    question.includes('how is my allowance calculated') ||
    question.includes('how is the allowance calculated') ||
    question.includes('how is my allowance determined') ||
    question.includes('definitieve berekening')
  ) {
    topic = 'definitive_calculation';

  // 6. Income change
  } else if (
    question.includes('income changed') ||
    question.includes('income has changed') ||
    question.includes('change in income') ||
    question.includes('report my income') ||
    question.includes('report income') ||
    question.includes('income increase') ||
    question.includes('income increased') ||
    question.includes('income decreased') ||
    question.includes('income decrease') ||
    question.includes('new income') ||
    question.includes('salary changed') ||
    question.includes('inkomen veranderd') ||
    question.includes('inkomenswijziging')
  ) {
    topic = 'income_change';
  }

  return topic;
}

/*
 * First classify the current question by itself.
 * This allows a follow-up to move to a different topic, such as:
 * "What if I cannot pay it?" → payment_arrangement
 */
let topic = classifyTopic(originalQuestion);

let usedConversationContext = false;
let previousUserQuestion = '';

/*
 * When the current question is vague, search backward through
 * earlier user messages until a recognizable topic is found.
 */
if (!topic) {
  for (const message of previousUserMessages) {
    const candidateQuestion = message.content.trim();
    const candidateTopic = classifyTopic(candidateQuestion);

    if (candidateTopic) {
      topic = candidateTopic;
      previousUserQuestion = candidateQuestion;
      usedConversationContext = true;
      break;
    }
  }
}

/*
 * Build a clearer query for vector retrieval.
 *
 * The public question remains unchanged, but a vague follow-up such as
 * "What is the phone number?" becomes:
 *
 * Previous question: ...
 * Follow-up question: What is the phone number?
 */
const searchQuestion =
  usedConversationContext && previousUserQuestion
    ? `Previous question: ${previousUserQuestion}\nFollow-up question: ${originalQuestion}`
    : originalQuestion;

return {
  json: {
    ...$json,
    question: originalQuestion,
    history,
    topic,
    search_question: searchQuestion,
    conversation_context: {
      previous_user_question: previousUserQuestion,
      previous_assistant_answer: previousAssistantAnswer,
      used_for_topic: usedConversationContext,
    },
  },
};

const results = $input.all();

const classified = $('Classify Topic').first().json;

const history = Array.isArray(classified.history)
  ? classified.history
  : [];

const context = results
  .map((item, index) => {
    const row = item.json;

    return [
      `Source ${index + 1}`,
      `Title: ${row.source_title}`,
      `Topic: ${row.topic}`,
      `URL: ${row.source_url}`,
      `Content: ${row.content}`,
    ].join('\n');
  })
  .join('\n\n---\n\n');

return [
  {
    json: {
      question: classified.question,
      topic: classified.topic,
      search_question:
        classified.search_question || classified.question,
      history,
      conversation_context:
        classified.conversation_context || {
          previous_user_question: '',
          previous_assistant_answer: '',
          used_for_topic: false,
        },
      context,
      sources: results.map((item) => ({
        source_id: item.json.source_id,
        source_title: item.json.source_title,
        source_url: item.json.source_url,
        similarity: item.json.similarity,
      })),
    },
  },
];

