={{ (() => {
  const question = String($json.question || '').trim();

  const history = Array.isArray($json.history)
    ? $json.history
        .filter(message =>
          message &&
          typeof message.content === 'string' &&
          ['user', 'assistant'].includes(message.role)
        )
        .slice(-6)
    : [];

  /*
   * The frontend currently adds the new user question to history
   * before sending the request. Remove that duplicate here.
   */
  if (
    history.length > 0 &&
    history[history.length - 1].role === 'user' &&
    history[history.length - 1].content.trim() === question
  ) {
    history.pop();
  }

  const conversationText = history.length > 0
    ? history
        .map(message => {
          const speaker =
            message.role === 'user'
              ? 'User'
              : 'GovGuide AI';

          return `${speaker}: ${message.content.trim()}`;
        })
        .join('\n\n')
    : 'No previous conversation.';

  return JSON.stringify({
    model: "qwen2.5:3b-instruct",
    stream: false,
    keep_alive: "30m",
    options: {
      temperature: 0.2,
      num_predict: 180,
      num_ctx: 4096
    },
    messages: [
      {
        role: "system",
        content: [
          "You are GovGuide AI.",
          "Return only the final answer.",
          "Do not describe your reasoning or review the sources aloud.",
          "Answer only in English.",
          "Use conversation history only to understand references and follow-up questions.",
          "Do not treat conversation history as an authoritative factual source.",
          "Use only the official source context provided for factual claims.",
          "Only state facts that are explicitly present in the provided context.",
          "Do not infer legal effects, payment consequences, eligibility, exceptions, or procedures that are not clearly stated.",
          "Do not invent facts, deadlines, amounts, conditions, or procedures.",
          "When a claim is uncertain or unsupported, omit it.",
          "Answer the current question, not the earlier question.",
          "Answer the current question in the first sentence.",
          "If the requested detail is not present in the official source context, say that clearly and briefly.",
          "Do not repeat unrelated details from earlier answers.",
          "Give a direct practical answer in no more than three short paragraphs.",
          "Do not include a Sources section or any URLs in the answer. Source URLs are returned separately by the API."
        ].join("\n")
      },
      {
        role: "user",
        content:
          "Recent conversation:\n" +
          conversationText +
          "\n\nCurrent question:\n" +
          question +
          "\n\nOfficial source context:\n" +
          $json.context
      }
    ]
  });
})() }}

