const rawAnswer = String($json.message?.content ?? '').trim();

if (!rawAnswer) {
  throw new Error('Ollama did not return an answer in message.content');
}

const contextData = $('Build Answer Context').first().json;

// Remove explicit thinking tags if present.
let answer = rawAnswer
  .replace(/<think>[\s\S]*?<\/think>/gi, '')
  .replace(/<\/?think>/gi, '')
  .trim();

// Qwen sometimes writes reasoning directly into message.content without tags.
// Keep only the final-answer section when a clear transition is present.
const transitionPatterns = [
  /\n\s*(?:final answer|answer)\s*:\s*/i,
  /\n\s*(?:therefore|so),?\s+(?=you|the)/i,
];

for (const pattern of transitionPatterns) {
  const match = answer.match(pattern);

  if (match?.index !== undefined) {
    answer = answer
      .slice(match.index + match[0].length)
      .trim();
    break;
  }
}

// Fallback for conversational reasoning openings.
const reasoningOpenings = [
  'Okay, let',
  "Let's tackle",
  'The user is asking',
  'I need to',
  'First, I need to',
  'Looking at Source',
];

if (reasoningOpenings.some(prefix => answer.startsWith(prefix))) {
  const paragraphs = answer
    .split(/\n{2,}/)
    .map(part => part.trim())
    .filter(Boolean);

  const finalParagraphIndex = paragraphs.findIndex(part =>
    /^(you can|you must|you should|if you|to object|submit|send|contact)/i.test(part)
  );

  if (finalParagraphIndex >= 0) {
    answer = paragraphs.slice(finalParagraphIndex).join('\n\n');
  }
}

if (!answer) {
  throw new Error('The final answer was empty after removing reasoning text');
}

const uniqueSources = Array.from(
  new Map(
    contextData.sources.map(source => [
      source.source_url,
      {
        source_id: source.source_id,
        source_title: source.source_title,
        source_url: source.source_url,
      },
    ])
  ).values()
);

return {
  json: {
    question: contextData.question,
    topic: contextData.topic,
    answer,
    sources: uniqueSources,
  },
};

const rawQuestion = $json.question;

const history = Array.isArray($json.history)
  ? $json.history
  : [];

if (typeof rawQuestion !== 'string') {
  return {
    json: {
      ...$json,
      question: '',
      history,
      valid: false,
      status_code: 400,
      error_code: 'INVALID_QUESTION_TYPE',
      error: 'The request body must contain a question as text.',
    },
  };
}

const question = rawQuestion.trim();

if (!question) {
  return {
    json: {
      ...$json,
      question,
      history,
      valid: false,
      status_code: 400,
      error_code: 'EMPTY_QUESTION',
      error: 'The question cannot be empty.',
    },
  };
}

if (question.length < 5) {
  return {
    json: {
      ...$json,
      question,
      history,
      valid: false,
      status_code: 400,
      error_code: 'QUESTION_TOO_SHORT',
      error: 'Please provide a more complete question.',
    },
  };
}

if (question.length > 1000) {
  return {
    json: {
      ...$json,
      question,
      history,
      valid: false,
      status_code: 400,
      error_code: 'QUESTION_TOO_LONG',
      error: 'The question is too long. Please limit it to 1000 characters.',
    },
  };
}

return {
  json: {
    ...$json,
    question,
    history,
    valid: true,
  },
};

