parameters.jsCode:
const finalResult = $json;
const testCase = $('Test Question').first().json;

const actualTopic = finalResult.topic ?? null;
const actualSourceIds = Array.isArray(finalResult.sources)
  ? finalResult.sources.map(source => source.source_id)
  : [];

const topicPassed = actualTopic === testCase.expected_topic;
const sourcePassed = actualSourceIds.includes(testCase.expected_source_id);

return {
  json: {
    test_case_id: testCase.test_case_id,
    question: testCase.question,

    expected_topic: testCase.expected_topic,
    actual_topic: actualTopic,
    topic_passed: topicPassed,

    expected_source_id: testCase.expected_source_id,
    actual_source_ids: actualSourceIds,
    source_passed: sourcePassed,

    overall_passed: topicPassed && sourcePassed,

    answer: finalResult.answer,
  },
};
